use std::sync::atomic::{AtomicU8, Ordering};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Lang {
    Zh,
    En,
}

impl Lang {
    pub const ALL: [Lang; 2] = [Lang::Zh, Lang::En];

    pub fn as_str(self) -> &'static str {
        match self {
            Lang::Zh => "zh",
            Lang::En => "en",
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Lang::Zh => "中文",
            Lang::En => "English",
        }
    }

    pub fn other(self) -> Lang {
        match self {
            Lang::Zh => Lang::En,
            Lang::En => Lang::Zh,
        }
    }
}

static LANG: AtomicU8 = AtomicU8::new(0);

thread_local! {
    static SAYING: std::cell::Cell<Option<Lang>> = const { std::cell::Cell::new(None) };
}

pub fn lang() -> Lang {
    if let Some(l) = SAYING.with(|c| c.get()) {
        return l;
    }
    if LANG.load(Ordering::Relaxed) == 0 {
        Lang::Zh
    } else {
        Lang::En
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct Words {
    pub zh: String,
    pub en: String,
}

impl Words {
    pub fn plain(s: impl Into<String>) -> Words {
        let s = s.into();
        Words { zh: s.clone(), en: s }
    }

    pub fn of(&self, l: Lang) -> &str {
        match l {
            Lang::Zh => &self.zh,
            Lang::En => &self.en,
        }
    }

    pub fn spoken(&self) -> &str {
        self.of(lang())
    }
}

impl From<String> for Words {
    fn from(s: String) -> Words {
        Words::plain(s)
    }
}

impl From<&str> for Words {
    fn from(s: &str) -> Words {
        Words::plain(s)
    }
}

impl From<&String> for Words {
    fn from(s: &String) -> Words {
        Words::plain(s.as_str())
    }
}

pub fn both_of<T: Into<String>>(words: impl Fn() -> T) -> Words {
    struct Back(Option<Lang>);
    impl Drop for Back {
        fn drop(&mut self) {
            SAYING.with(|c| c.set(self.0));
        }
    }
    let say = |l: Lang| -> String {
        let _back = Back(SAYING.with(|c| c.replace(Some(l))));
        words().into()
    };
    Words { zh: say(Lang::Zh), en: say(Lang::En) }
}

pub fn set(l: Lang) {
    crate::trace::mark(crate::feature::Feature::H5);
    LANG.store(if l == Lang::Zh { 0 } else { 1 }, Ordering::Relaxed);
}

