pub fn t(k: Key) -> &'static str {
    let row = TABLE.iter().find(|(key, _, _)| *key == k);
    match (row, lang()) {
        (Some((_, zh, _)), Lang::Zh) => zh,
        (Some((_, _, en)), Lang::En) => en,
        (None, _) => "?",
    }
}

pub fn both(k: Key) -> (&'static str, &'static str) {
    match TABLE.iter().find(|(key, _, _)| *key == k) {
        Some((_, zh, en)) => (zh, en),
        None => ("?", "?"),
    }
}

pub fn twin(s: &str) -> Option<&'static str> {
    TABLE.iter().find_map(|(_, zh, en)| match lang() {
        Lang::Zh if *zh == s => Some(*en),
        Lang::En if *en == s => Some(*zh),
        _ => None,
    })
}

pub fn filln(k: Key, args: &[&str]) -> String {
    let tpl = t(k);
    let mut out = String::with_capacity(tpl.len() + 16);
    let mut rest = tpl;
    while let Some(i) = rest.find('{') {
        out.push_str(&rest[..i]);
        let after = &rest[i + 1..];
        match after.find('}').and_then(|j| after[..j].parse::<usize>().ok().map(|n| (j, n))) {
            Some((j, n)) if n < args.len() => {
                out.push_str(args[n]);
                rest = &after[j + 1..];
            }
            _ => {
                out.push('{');
                rest = after;
            }
        }
    }
    out.push_str(rest);
    out
}

pub fn fill1(k: Key, a: &str) -> String {
    filln(k, &[a])
}

pub fn fill2(k: Key, a: &str, b: &str) -> String {
    filln(k, &[a, b])
}

pub fn fill3(k: Key, a: &str, b: &str, c: &str) -> String {
    filln(k, &[a, b, c])
}

pub fn trouble() -> Vec<String> {
    let mut bad = Vec::new();
    if TABLE.len() != Key::ALL.len() {
        bad.push(format!("表 {} 行,键 {} 枚", TABLE.len(), Key::ALL.len()));
    }
    for k in Key::ALL {
        let n = TABLE.iter().filter(|(key, _, _)| *key == k).count();
        if n != 1 {
            bad.push(format!("{k:?} 在表里 {n} 行"));
        }
    }
    for (k, zh, en) in TABLE {
        if zh.trim().is_empty() {
            bad.push(format!("{k:?} 的中文是空的"));
        }
        if en.trim().is_empty() {
            bad.push(format!("{k:?} 的英文是空的"));
        }
    }
    for (k, zh, en) in TABLE {
        let slots = |text: &str| -> Result<Vec<usize>, String> {
            let mut out: Vec<usize> = Vec::new();
            let b = text.as_bytes();
            let mut i = 0usize;
            while i < b.len() {
                if b[i] == b'{' {
                    let Some(end) = text[i..].find('}').map(|e| i + e) else {
                        return Err(format!("{}处花括号没有合上", i));
                    };
                    let inner = &text[i + 1..end];
                    match inner.parse::<usize>() {
                        Ok(n) => out.push(n),
                        Err(_) => return Err(format!("`{{{inner}}}` 不是 `{{n}}` 那一形")),
                    }
                    i = end + 1;
                    continue;
                }
                i += 1;
            }
            out.sort_unstable();
            out.dedup();
            Ok(out)
        };
        match (slots(zh), slots(en)) {
            (Err(why), _) => bad.push(format!("{k:?} 的中文填格写坏了:{why}")),
            (_, Err(why)) => bad.push(format!("{k:?} 的英文填格写坏了:{why}")),
            (Ok(a), Ok(b)) if a != b => bad.push(format!("{k:?} 两语的填格不一样:中 {a:?} 英 {b:?}")),
            _ => {}
        }
    }
    for (i, (k, zh, en)) in TABLE.iter().enumerate() {
        for (k2, zh2, en2) in TABLE.iter().skip(i + 1) {
            if zh == zh2 {
                bad.push(format!("{k:?} 与 {k2:?} 的中文撞了:{zh}"));
            }
            if en == en2 {
                bad.push(format!("{k:?} 与 {k2:?} 的英文撞了:{en}"));
            }
        }
    }
    bad
}
